/**
 * Users Page
 *
 * Page for managing users (admins and agents)
 * Phase 5: User Story 3 - Agent User Creation and Line Assignment
 */

import { useState, useEffect } from 'react';
import { Alert, Modal } from 'react-bootstrap';
import UserListTable from '../../components/users/UserListTable';
import UserForm from '../../components/users/UserForm';
import LineAssignmentModal from '../../components/users/LineAssignmentModal';
import UserFiltersModal from '../../components/users/UserFiltersModal';
import useUsersStore from '../../store/usersStore';
import './Users.scss';

const Users = () => {
  const {
    users,
    loading,
    error,
    fetchUsers,
    createUser,
    updateUser,
    deleteUser,
    activateUser,
    assignLinesToUser,
    clearError
  } = useUsersStore();

  const [showUserModal, setShowUserModal] = useState(false);
  const [showLineAssignmentModal, setShowLineAssignmentModal] = useState(false);
  const [showFiltersModal, setShowFiltersModal] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);
  const [successMessage, setSuccessMessage] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [filters, setFilters] = useState({
    userType: 'all',
    lineId: 'all',
    role: 'all',
    sortBy: 'all'
  });

  useEffect(() => {
    fetchUsers();
  }, [fetchUsers]);

  const handleAddUser = () => {
    setSelectedUser(null);
    setShowUserModal(true);
  };

  const handleEditUser = (user) => {
    setSelectedUser(user);
    setShowUserModal(true);
  };

  const handleManageLines = (user) => {
    setSelectedUser(user);
    setShowLineAssignmentModal(true);
  };

  const handleCloseUserModal = () => {
    setShowUserModal(false);
    setSelectedUser(null);
  };

  const handleCloseLineAssignmentModal = () => {
    setShowLineAssignmentModal(false);
    setSelectedUser(null);
  };

  const handleUserFormSubmit = async (formData) => {
    try {
      let userId;

      if (selectedUser) {
        // Update existing user
        await updateUser(selectedUser.id, formData);
        userId = selectedUser.id;

        // Update line assignments if role is agent
        if ((formData.role === 'agent' || formData.role === 'admin') && formData.selectedLines) {
          await assignLinesToUser(userId, formData.selectedLines);
        }

        setSuccessMessage('Usuario actualizado exitosamente');
      } else {
        // Create new user

        const response = await createUser(formData);

        userId = response.id;

        if (formData.role === 'agent' && formData.selectedLines && formData.selectedLines.length > 0) {

          await assignLinesToUser(userId, formData.selectedLines);
        }

        setSuccessMessage('Usuario creado exitosamente');
      }

      setShowUserModal(false);
      setSelectedUser(null);
      setTimeout(() => setSuccessMessage(''), 3000);
      fetchUsers(); // Refresh list after save
    } catch (err) {
      console.error('User save error:', err);
    }
  };

  const handleLineAssignmentSuccess = () => {
    setShowLineAssignmentModal(false);
    setSelectedUser(null);
    setSuccessMessage('Line assignments updated successfully');
    setTimeout(() => setSuccessMessage(''), 3000);
    fetchUsers(); // Refresh list after assignment
  };

  const handleDeleteUser = async (userId) => {
    const userToDelete = users.find(u => u.id === userId);

    if (!userToDelete) return;

    if (!window.confirm(`Are you sure you want to delete user "${userToDelete.name}"? This action cannot be undone.`)) {
      return;
    }

    try {
      await deleteUser(userId);
      setSuccessMessage('User deleted successfully');
      setTimeout(() => setSuccessMessage(''), 3000);
      fetchUsers(); // Refresh list after delete
    } catch (err) {
      console.error('Delete error:', err);
    }
  };

  const handleActivateUser = async (userId) => {
    const userToActivate = users.find(u => u.id === userId);

    if (!userToActivate) return;

    if (!window.confirm(`¿Estás seguro de que deseas activar al usuario "${userToActivate.name}"?`)) {
      return;
    }

    try {
      await activateUser(userId);
      setSuccessMessage('Usuario activado exitosamente');
      setTimeout(() => setSuccessMessage(''), 3000);
      fetchUsers(); // Refresh list after activation
    } catch (err) {
      console.error('Activate error:', err);
    }
  };

  // Apply filters and sorting to users
  const getFilteredAndSortedUsers = () => {
    let filtered = users.filter(user => {
      // Search filter
      const matchesSearch = searchTerm === '' ||
        user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        user.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (user.phone_number && user.phone_number.includes(searchTerm));

      // User type filter (same as role but from userType field)
      const matchesUserType = filters.userType === 'all' || user.role === filters.userType;

      // Role filter
      const matchesRole = filters.role === 'all' || user.role === filters.role;

      // Phone Line filter - check if user has the selected line assigned
      const matchesLine = filters.lineId === 'all' ||
        (user.assignedLines && user.assignedLines.some(line =>
          line.id === parseInt(filters.lineId) || line.line_id === parseInt(filters.lineId)
        ));

      return matchesSearch && matchesUserType && matchesRole && matchesLine;
    });

    // Apply sorting
    if (filters.sortBy !== 'all') {
      filtered = [...filtered].sort((a, b) => {
        const dateA = new Date(a.created_at || a.id);
        const dateB = new Date(b.created_at || b.id);

        if (filters.sortBy === 'newest') {
          return dateB - dateA; // Most recent first
        } else if (filters.sortBy === 'oldest') {
          return dateA - dateB; // Oldest first
        }
        return 0;
      });
    }

    return filtered;
  };

  const filteredUsers = getFilteredAndSortedUsers();

  const handleApplyFilters = (newFilters) => {
    setFilters(newFilters);
  };

  const handleOpenFiltersModal = () => {
    setShowFiltersModal(true);
  };

  const handleCloseFiltersModal = () => {
    setShowFiltersModal(false);
  };

  // Count active filters
  const getActiveFiltersCount = () => {
    let count = 0;
    if (filters.userType !== 'all') count++;
    if (filters.lineId !== 'all') count++;
    if (filters.role !== 'all') count++;
    if (filters.sortBy !== 'all') count++;
    return count;
  };

  return (
    <div className="users-page">
      <div className="page-header">
        <div>
          <h1 className="page-title">Usuarios</h1>
          <p className="page-subtitle">
            Gestiona los usuarios y administradores del sistema
          </p>
        </div>
      </div>

      {error && (
        <Alert
          variant="danger"
          dismissible
          onClose={clearError}
          className="mb-4"
        >
          {error}
        </Alert>
      )}

      {successMessage && (
        <Alert
          variant="success"
          dismissible
          onClose={() => setSuccessMessage('')}
          className="mb-4"
        >
          {successMessage}
        </Alert>
      )}

      <UserListTable
        users={filteredUsers}
        loading={loading}
        onEdit={handleEditUser}
        onDelete={handleDeleteUser}
        onActivate={handleActivateUser}
        onManageLines={handleManageLines}
        onAdd={handleAddUser}
        onOpenFilters={handleOpenFiltersModal}
        searchTerm={searchTerm}
        onSearchChange={setSearchTerm}
      />

      {/* User Creation/Edit Modal */}
      <Modal
        show={showUserModal}
        onHide={handleCloseUserModal}
        size="lg"
        scrollable
        backdrop="static"
        keyboard={!loading}
      >
        <Modal.Header closeButton={!loading}>
          <Modal.Title>
            <i className="bi bi-person me-2"></i>
            {selectedUser ? 'Editar usuario' : 'Agregar usuario'}
          </Modal.Title>
        </Modal.Header>
        <UserForm
          user={selectedUser}
          onSubmit={handleUserFormSubmit}
          onCancel={handleCloseUserModal}
          loading={loading}
          error={error}
        />
      </Modal>

      {/* Line Assignment Modal */}
      <LineAssignmentModal
        show={showLineAssignmentModal}
        user={selectedUser}
        onClose={handleCloseLineAssignmentModal}
        onSuccess={handleLineAssignmentSuccess}
      />

      {/* Advanced Filters Modal */}
      <UserFiltersModal
        show={showFiltersModal}
        onHide={handleCloseFiltersModal}
        onApplyFilters={handleApplyFilters}
        currentFilters={filters}
      />
    </div>
  );
};

export default Users;

