/**
 * POST /api/v1/users/:userId/lines
 *
 * Assign lines to a user
 * Phase 5: User Story 3 - Agent User Creation and Line Assignment
 */

import { Router } from 'express';
import PhoneLineAssignmentService from '../../../services/PhoneLineAssignmentService.js';
import { authenticateJWT } from '../../../middleware/authenticateJWT.js';
import { authorizeRole } from '../../../middleware/authorizeRole.js';
import { AppError } from '../../../middleware/errorHandler.js';

const router = Router();

/**
 * @route POST /api/v1/users/:userId/lines
 * @desc Assign lines to a user (agent only)
 * @access Admin only
 */
router.post('/:userId/lines', authenticateJWT, authorizeRole(['admin']), async (req, res, next) => {
  try {
    const { userId } = req.params;
    const { lineIds } = req.body;

    if (!userId || isNaN(parseInt(userId))) {
      throw new AppError('Invalid user ID', 400);
    }

    if (!lineIds || !Array.isArray(lineIds) || lineIds.length === 0) {
      throw new AppError('lineIds must be a non-empty array', 400);
    }

    // Validate all lineIds are numbers
    const invalidIds = lineIds.filter(id => isNaN(parseInt(id)));
    if (invalidIds.length > 0) {
      throw new AppError('All lineIds must be valid numbers', 400);
    }

    const result = await PhoneLineAssignmentService.replaceUserPhoneLineAssignments(
      parseInt(userId),
      lineIds.map(id => parseInt(id))
    );

    res.status(200).json({
      success: true,
      message: result.message,
      data: {
        assignedCount: result.assignedCount
      }
    });
  } catch (error) {
    next(error);
  }
});

export default router;

