/**
 * Phone Line Assignment Service
 *
 * Handles assignment of Phone Lines to agent users
 * Uses Sequelize ORM for database operations
 */

import { User, PhoneLine, PhoneLineUserAssignment, Role, WhatsAppLine, LineUserAssignment } from '../models/sequelize/associations.js';
import sequelize from '../config/sequelize.js';
import { AppError } from '../middleware/errorHandler.js';

class PhoneLineAssignmentService {
  /**
   * Assign phone lines to a user (agent or admin)
   * Uses transaction to ensure atomicity
   *
   * @param {number} userId - User ID
   * @param {number[]} phoneLineIds - Array of phone line IDs to assign
   * @returns {Promise<Object>} Assignment result
   */
  async assignPhoneLinesToUser(userId, phoneLineIds) {
    const transaction = await sequelize.transaction();

    try {
      // Validate user exists and is an agent or admin
      const user = await User.findByPk(userId, {
        include: [{
          model: Role,
          as: 'role',
          attributes: ['role_name']
        }],
        transaction
      });

      if (!user) {
        throw new AppError('User not found', 404);
      }

      if (user.role.role_name !== 'agent' && user.role.role_name !== 'admin') {
        throw new AppError('Only agents and admins can be assigned phone lines', 400);
      }

      if (!user.is_active) {
        throw new AppError('Cannot assign phone lines to inactive user', 400);
      }

      // Validate all phone lines exist and are active
      const phoneLines = await PhoneLine.findAll({
        where: { id: phoneLineIds },
        attributes: ['id', 'is_active', 'phone_number'],
        transaction
      });

      if (phoneLines.length !== phoneLineIds.length) {
        throw new AppError('One or more phone lines not found', 404);
      }

      const inactiveLines = phoneLines.filter(line => !line.is_active);
      if (inactiveLines.length > 0) {
        throw new AppError('Cannot assign inactive phone lines', 400);
      }

      // Create assignments (ignore duplicates)
      const assignments = phoneLineIds.map(phoneLineId => ({
        user_id: userId,
        phone_line_id: phoneLineId
      }));

      await PhoneLineUserAssignment.bulkCreate(assignments, {
        ignoreDuplicates: true,
        transaction
      });

      // Also assign to WhatsAppLine if exists (for legacy compatibility)
      const phoneNumbers = phoneLines.map(line => line.phone_number);
      const whatsappLines = await WhatsAppLine.findAll({
        where: { phone_number: phoneNumbers, is_active: true },
        attributes: ['id', 'phone_number'],
        transaction
      });

      if (whatsappLines.length > 0) {
        const whatsappAssignments = whatsappLines.map(line => ({
          user_id: userId,
          line_id: line.id
        }));

        await LineUserAssignment.bulkCreate(whatsappAssignments, {
          ignoreDuplicates: true,
          transaction
        });
      }

      await transaction.commit();

      return {
        success: true,
        message: `Successfully assigned ${phoneLineIds.length} phone line(s) to user`,
        assignedCount: phoneLineIds.length
      };
    } catch (error) {
      await transaction.rollback();

      if (error instanceof AppError) throw error;
      console.error('Assign phone lines to user error:', error);
      throw new AppError('Failed to assign phone lines to user', 500);
    }
  }

  /**
   * Remove phone line assignment from user
   *
   * @param {number} userId - User ID
   * @param {number} phoneLineId - Phone Line ID to remove
   * @returns {Promise<Object>} Removal result
   */
  async removePhoneLineFromUser(userId, phoneLineId) {
    const transaction = await sequelize.transaction();

    try {
      // Get phone line to find matching WhatsAppLine
      const phoneLine = await PhoneLine.findByPk(phoneLineId, {
        attributes: ['phone_number'],
        transaction
      });

      if (!phoneLine) {
        throw new AppError('Phone line not found', 404);
      }

      // Remove PhoneLine assignment
      const deleted = await PhoneLineUserAssignment.destroy({
        where: {
          user_id: userId,
          phone_line_id: phoneLineId
        },
        transaction
      });

      if (deleted === 0) {
        throw new AppError('Phone line assignment not found', 404);
      }

      // Also remove WhatsAppLine assignment if exists (for legacy compatibility)
      const whatsappLine = await WhatsAppLine.findOne({
        where: { phone_number: phoneLine.phone_number, is_active: true },
        attributes: ['id'],
        transaction
      });

      if (whatsappLine) {
        await LineUserAssignment.destroy({
          where: {
            user_id: userId,
            line_id: whatsappLine.id
          },
          transaction
        });
      }

      await transaction.commit();

      return {
        success: true,
        message: 'Phone line assignment removed successfully'
      };
    } catch (error) {
      await transaction.rollback();

      if (error instanceof AppError) throw error;
      console.error('Remove phone line from user error:', error);
      throw new AppError('Failed to remove phone line assignment', 500);
    }
  }

  /**
   * Get all phone lines assigned to a user
   *
   * @param {number} userId - User ID
   * @returns {Promise<Array>} Assigned phone lines
   */
  async getUserAssignedPhoneLines(userId) {
    try {
      const user = await User.findByPk(userId, {
        include: [
          {
            model: PhoneLine,
            as: 'assignedPhoneLines',
            attributes: [
              'id',
              'name',
              'phone_number',
              'display_phone_number',
              'verified_name',
              'waba_id',
              'quality_rating',
              'is_active'
            ],
            through: {
              attributes: ['assigned_at']
            }
          }
        ]
      });

      if (!user) {
        throw new AppError('User not found', 404);
      }

      return user.assignedPhoneLines.map(line => ({
        id: line.id,
        name: line.name,
        phone_number: line.phone_number,
        display_phone_number: line.display_phone_number,
        verified_name: line.verified_name,
        waba_id: line.waba_id,
        quality_rating: line.quality_rating,
        is_active: line.is_active,
        assigned_at: line.PhoneLineUserAssignment.assigned_at
      }));
    } catch (error) {
      if (error instanceof AppError) throw error;
      console.error('Get user assigned phone lines error:', error);
      throw new AppError('Failed to get assigned phone lines', 500);
    }
  }

  /**
   * Get all users assigned to a phone line
   *
   * @param {number} phoneLineId - Phone Line ID
   * @returns {Promise<Array>} Assigned users
   */
  async getPhoneLineAssignedUsers(phoneLineId) {
    try {
      const phoneLine = await PhoneLine.findByPk(phoneLineId, {
        include: [
          {
            model: User,
            as: 'assignedUsers',
            attributes: ['id', 'name', 'email', 'is_active'],
            through: {
              attributes: ['assigned_at']
            }
          }
        ]
      });

      if (!phoneLine) {
        throw new AppError('Phone line not found', 404);
      }

      return phoneLine.assignedUsers.map(user => ({
        id: user.id,
        name: user.name,
        email: user.email,
        is_active: user.is_active,
        assigned_at: user.PhoneLineUserAssignment.assigned_at
      }));
    } catch (error) {
      if (error instanceof AppError) throw error;
      console.error('Get phone line assigned users error:', error);
      throw new AppError('Failed to get assigned users', 500);
    }
  }

  /**
   * Replace all phone line assignments for a user (bulk update)
   *
   * @param {number} userId - User ID
   * @param {number[]} phoneLineIds - New array of phone line IDs
   * @returns {Promise<Object>} Update result
   */
  async replaceUserPhoneLineAssignments(userId, phoneLineIds) {
    const transaction = await sequelize.transaction();

    try {
      // Validate user exists and is an agent or admin
      const user = await User.findByPk(userId, {
        include: [{
          model: Role,
          as: 'role',
          attributes: ['role_name']
        }],
        transaction
      });

      if (!user) {
        throw new AppError('User not found', 404);
      }

      if (user.role.role_name !== 'agent' && user.role.role_name !== 'admin') {
        throw new AppError('Only agents and admins can be assigned phone lines', 400);
      }

      // Remove all existing assignments
      await PhoneLineUserAssignment.destroy({
        where: { user_id: userId },
        transaction
      });

      // Also remove WhatsAppLine assignments (for legacy compatibility)
      await LineUserAssignment.destroy({
        where: { user_id: userId },
        transaction
      });

      // Add new assignments if any
      if (phoneLineIds && phoneLineIds.length > 0) {
        // Validate all phone lines exist and are active
        const phoneLines = await PhoneLine.findAll({
          where: { id: phoneLineIds },
          attributes: ['id', 'is_active', 'phone_number'],
          transaction
        });

        if (phoneLines.length !== phoneLineIds.length) {
          throw new AppError('One or more phone lines not found', 404);
        }

        const inactiveLines = phoneLines.filter(line => !line.is_active);
        if (inactiveLines.length > 0) {
          throw new AppError('Cannot assign inactive phone lines', 400);
        }

        const assignments = phoneLineIds.map(phoneLineId => ({
          user_id: userId,
          phone_line_id: phoneLineId
        }));

        await PhoneLineUserAssignment.bulkCreate(assignments, {
          transaction
        });

        // Also assign to WhatsAppLine if exists (for legacy compatibility)
        const phoneNumbers = phoneLines.map(line => line.phone_number);
        const whatsappLines = await WhatsAppLine.findAll({
          where: { phone_number: phoneNumbers, is_active: true },
          attributes: ['id', 'phone_number'],
          transaction
        });

        if (whatsappLines.length > 0) {
          const whatsappAssignments = whatsappLines.map(line => ({
            user_id: userId,
            line_id: line.id
          }));

          await LineUserAssignment.bulkCreate(whatsappAssignments, {
            transaction
          });
        }
      }

      await transaction.commit();

      return {
        success: true,
        message: 'Phone line assignments updated successfully',
        assignedCount: phoneLineIds ? phoneLineIds.length : 0
      };
    } catch (error) {
      await transaction.rollback();

      if (error instanceof AppError) throw error;
      console.error('Replace user phone line assignments error:', error);
      throw new AppError('Failed to update phone line assignments', 500);
    }
  }

  /**
   * Replace all user assignments for a phone line (bulk update)
   * This replaces ALL users assigned to a specific phone line
   *
   * @param {number} phoneLineId - Phone Line ID
   * @param {number[]} userIds - New array of user IDs to assign
   * @returns {Promise<Object>} Update result
   */
  async replacePhoneLineUserAssignments(phoneLineId, userIds) {
    const transaction = await sequelize.transaction();

    try {
      // Validate phone line exists and is active
      const phoneLine = await PhoneLine.findByPk(phoneLineId, { attributes: ['id', 'is_active', 'phone_number'], transaction });

      if (!phoneLine) {
        throw new AppError('Phone line not found', 404);
      }

      if (!phoneLine.is_active) {
        throw new AppError('Cannot assign users to inactive phone line', 400);
      }

      // Remove all existing user assignments for this phone line
      await PhoneLineUserAssignment.destroy({
        where: { phone_line_id: phoneLineId },
        transaction
      });

      // Also remove WhatsAppLine user assignments (for legacy compatibility)
      const whatsappLine = await WhatsAppLine.findOne({
        where: { phone_number: phoneLine.phone_number, is_active: true },
        attributes: ['id'],
        transaction
      });

      if (whatsappLine) {
        await LineUserAssignment.destroy({
          where: { line_id: whatsappLine.id },
          transaction
        });
      }

      // Add new user assignments if any
      if (userIds && userIds.length > 0) {
        // Validate all users exist and are agents or admins
        const users = await User.findAll({
          where: { id: userIds },
          include: [{
            model: Role,
            as: 'role',
            attributes: ['role_name']
          }],
          transaction
        });

        if (users.length !== userIds.length) {
          throw new AppError('One or more users not found', 404);
        }

        // Validate all users are agents or admins and active
        const invalidUsers = users.filter(user =>
          (user.role.role_name !== 'agent' && user.role.role_name !== 'admin') || !user.is_active
        );

        if (invalidUsers.length > 0) {
          throw new AppError('All users must be active agents or admins', 400);
        }

        // Create new assignments
        const assignments = userIds.map(userId => ({
          user_id: userId,
          phone_line_id: phoneLineId
        }));

        await PhoneLineUserAssignment.bulkCreate(assignments, {
          transaction
        });

        // Also assign users to WhatsAppLine if exists (for legacy compatibility)
        if (whatsappLine) {
          const whatsappAssignments = userIds.map(userId => ({
            user_id: userId,
            line_id: whatsappLine.id
          }));

          await LineUserAssignment.bulkCreate(whatsappAssignments, {
            transaction
          });
        }
      }

      await transaction.commit();

      return {
        success: true,
        message: 'Phone line user assignments updated successfully',
        assignedCount: userIds ? userIds.length : 0
      };
    } catch (error) {
      await transaction.rollback();

      if (error instanceof AppError) throw error;
      console.error('Replace phone line user assignments error:', error);
      throw new AppError('Failed to update phone line user assignments', 500);
    }
  }

  /**
   * Get all active phone lines (for admins)
   *
   * @returns {Promise<Array>} All active phone lines
   */
  async getAllActivePhoneLines() {
    try {
      const phoneLines = await PhoneLine.findAll({
        where: { is_active: true },
        attributes: [
          'id',
          'name',
          'phone_number',
          'display_phone_number',
          'verified_name',
          'waba_id',
          'quality_rating',
          'is_active'
        ],
        order: [['name', 'ASC']]
      });

      return phoneLines.map(line => line.toJSON());
    } catch (error) {
      console.error('Get all active phone lines error:', error);
      throw new AppError('Failed to get active phone lines', 500);
    }
  }
}

export default new PhoneLineAssignmentService();

