/**
 * Sequelize Model Associations
 *
 * This file defines all relationships between Sequelize models.
 * Import all models and define associations in dependency order.
 *
 * Association Types:
 * - hasMany: One-to-many (e.g., Role has many Users)
 * - belongsTo: Many-to-one (e.g., User belongs to Role)
 * - belongsToMany: Many-to-many with junction table
 * - hasOne: One-to-one
 */

import Role from './Role.js';
import User from './User.js';
import WhatsAppLine from './WhatsAppLine.js';
import PhoneLine from './PhoneLine.js';
import LineUserAssignment from './LineUserAssignment.js';
import Lead from './Lead.js';
import Message from './Message.js';
import MessageTemplate from './MessageTemplate.js';
import ConversationAssignment from './ConversationAssignment.js';
import Configuration from './Configuration.js';
import AutomationRule from './AutomationRule.js';
import CampaignAgentAssignment from './CampaignAgentAssignment.js';

/**
 * Phase B: Role & User Associations
 *
 * Relationship: One Role has many Users, One User belongs to one Role
 */

// Role has many Users
Role.hasMany(User, {
  foreignKey: 'role_id',
  as: 'users',
  onDelete: 'RESTRICT', // Prevent deletion of role if users exist
  onUpdate: 'CASCADE',
});

// User belongs to one Role
User.belongsTo(Role, {
  foreignKey: 'role_id',
  as: 'role',
  onDelete: 'RESTRICT', // User cannot exist without a role
  onUpdate: 'CASCADE',
});

/**
 * Phase C: WhatsAppLine & LineUserAssignment Associations
 *
 * Relationship: Many-to-Many between Users (agents) and WhatsAppLines through LineUserAssignment
 */

// User belongs to many WhatsAppLines through LineUserAssignment
User.belongsToMany(WhatsAppLine, {
  through: LineUserAssignment,
  foreignKey: 'user_id',
  otherKey: 'line_id',
  as: 'assignedLines',
  onDelete: 'CASCADE', // Delete assignments when user is deleted
  onUpdate: 'CASCADE',
});

// WhatsAppLine belongs to many Users through LineUserAssignment
WhatsAppLine.belongsToMany(User, {
  through: LineUserAssignment,
  foreignKey: 'line_id',
  otherKey: 'user_id',
  as: 'assignedUsers',
  onDelete: 'CASCADE', // Delete assignments when line is deleted
  onUpdate: 'CASCADE',
});

// LineUserAssignment belongs to User
LineUserAssignment.belongsTo(User, {
  foreignKey: 'user_id',
  as: 'user',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// LineUserAssignment belongs to WhatsAppLine
LineUserAssignment.belongsTo(WhatsAppLine, {
  foreignKey: 'line_id',
  as: 'line',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// User has many LineUserAssignments
User.hasMany(LineUserAssignment, {
  foreignKey: 'user_id',
  as: 'lineAssignments',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// WhatsAppLine has many LineUserAssignments
WhatsAppLine.hasMany(LineUserAssignment, {
  foreignKey: 'line_id',
  as: 'userAssignments',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

/**
 * Phase C.1: PhoneLine
 *
 * PhoneLine is independent and relates to WABA ID (Meta ID string)
 * No direct association with WhatsAppLine needed
 * PhoneLine stores its own WABA reference
 */

/**
 * Phase D: Lead & Message Associations
 *
 * Relationships:
 * - WhatsAppLine has many Messages
 * - Lead has many Messages
 * - User has many Messages (as sender for outgoing messages)
 * - Message can reply to another Message (self-referential)
 */

// WhatsAppLine has many Messages
WhatsAppLine.hasMany(Message, {
  foreignKey: 'line_id',
  as: 'messages',
  onDelete: 'RESTRICT', // Cannot delete line if messages exist
  onUpdate: 'CASCADE',
});

// Message belongs to WhatsAppLine
Message.belongsTo(WhatsAppLine, {
  foreignKey: 'line_id',
  as: 'line',
  onDelete: 'RESTRICT',
  onUpdate: 'CASCADE',
});

// Lead has many Messages
Lead.hasMany(Message, {
  foreignKey: 'lead_id',
  as: 'messages',
  onDelete: 'SET NULL', // Preserve messages if lead is deleted
  onUpdate: 'CASCADE',
});

// Message belongs to Lead
Message.belongsTo(Lead, {
  foreignKey: 'lead_id',
  as: 'lead',
  onDelete: 'SET NULL',
  onUpdate: 'CASCADE',
});

// User has many Messages (as sender)
User.hasMany(Message, {
  foreignKey: 'user_id',
  as: 'sentMessages',
  onDelete: 'SET NULL', // Preserve messages if user is deleted
  onUpdate: 'CASCADE',
});

// Message belongs to User (sender)
Message.belongsTo(User, {
  foreignKey: 'user_id',
  as: 'sender',
  onDelete: 'SET NULL',
  onUpdate: 'CASCADE',
});

// Message can reply to another Message (self-referential)
Message.hasMany(Message, {
  foreignKey: 'reply_to_message_id',
  as: 'replies',
  onDelete: 'SET NULL',
  onUpdate: 'CASCADE',
});

Message.belongsTo(Message, {
  foreignKey: 'reply_to_message_id',
  as: 'parentMessage',
  onDelete: 'SET NULL',
  onUpdate: 'CASCADE',
});

/**
 * Phase E: MessageTemplate, ConversationAssignment, Configuration Associations
 *
 * Relationships:
 * - WhatsAppLine has many MessageTemplates
 * - MessageTemplate belongs to WhatsAppLine
 * - Message belongs to MessageTemplate (optional)
 * - ConversationAssignment belongs to User (assigned agent)
 * - ConversationAssignment belongs to User (assigning user)
 * - ConversationAssignment belongs to Lead (via phone_number)
 * - Configuration is standalone (singleton table)
 */

// WhatsAppLine has many MessageTemplates
WhatsAppLine.hasMany(MessageTemplate, {
  foreignKey: 'line_id',
  as: 'templates',
  onDelete: 'CASCADE', // Delete templates when line is deleted
  onUpdate: 'CASCADE',
});

// MessageTemplate belongs to WhatsAppLine
MessageTemplate.belongsTo(WhatsAppLine, {
  foreignKey: 'line_id',
  as: 'line',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// Message belongs to MessageTemplate (optional - for template messages)
Message.belongsTo(MessageTemplate, {
  foreignKey: 'template_id',
  as: 'template',
  onDelete: 'SET NULL', // Preserve message if template is deleted
  onUpdate: 'CASCADE',
});

// MessageTemplate has many Messages
MessageTemplate.hasMany(Message, {
  foreignKey: 'template_id',
  as: 'messages',
  onDelete: 'SET NULL',
  onUpdate: 'CASCADE',
});

// ConversationAssignment belongs to User (assigned agent)
ConversationAssignment.belongsTo(User, {
  foreignKey: 'assigned_user_id',
  as: 'assignedUser',
  onDelete: 'SET NULL', // Unassign conversation if user is deleted
  onUpdate: 'CASCADE',
});

// User has many ConversationAssignments (as assigned agent)
User.hasMany(ConversationAssignment, {
  foreignKey: 'assigned_user_id',
  as: 'conversationAssignments',
  onDelete: 'SET NULL',
  onUpdate: 'CASCADE',
});

// ConversationAssignment belongs to User (assigning user)
ConversationAssignment.belongsTo(User, {
  foreignKey: 'assigned_by_user_id',
  as: 'assignedBy',
  onDelete: 'SET NULL', // Keep assignment record if assigning user is deleted
  onUpdate: 'CASCADE',
});

// User has many ConversationAssignments (as assigning user)
User.hasMany(ConversationAssignment, {
  foreignKey: 'assigned_by_user_id',
  as: 'assignmentsMade',
  onDelete: 'SET NULL',
  onUpdate: 'CASCADE',
});

// ConversationAssignment belongs to WhatsAppLine
ConversationAssignment.belongsTo(WhatsAppLine, {
  foreignKey: 'line_id',
  as: 'line',
  onDelete: 'CASCADE', // Delete assignment if line is deleted
  onUpdate: 'CASCADE',
});

// WhatsAppLine has many ConversationAssignments
WhatsAppLine.hasMany(ConversationAssignment, {
  foreignKey: 'line_id',
  as: 'conversationAssignments',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

/**
 * Export all models with associations
 *
 * This allows importing models with associations already defined:
 * import { User, Role, WhatsAppLine, PhoneLine, LineUserAssignment, Lead, Message, MessageTemplate, ConversationAssignment, Configuration } from './models/sequelize/associations.js';
 */
export {
  Role,
  User,
  WhatsAppLine,
  PhoneLine,
  LineUserAssignment,
  Lead,
  Message,
  MessageTemplate,
  ConversationAssignment,
  Configuration
};

// Import PhoneLineUserAssignment
import PhoneLineUserAssignment from './PhoneLineUserAssignment.js';

/**
 * Phone Line User Assignments (Many-to-Many between Users and PhoneLines)
 */

// User belongs to many PhoneLines through PhoneLineUserAssignment
User.belongsToMany(PhoneLine, {
  through: PhoneLineUserAssignment,
  foreignKey: 'user_id',
  otherKey: 'phone_line_id',
  as: 'assignedPhoneLines',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// PhoneLine belongs to many Users through PhoneLineUserAssignment
PhoneLine.belongsToMany(User, {
  through: PhoneLineUserAssignment,
  foreignKey: 'phone_line_id',
  otherKey: 'user_id',
  as: 'assignedUsers',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// PhoneLineUserAssignment belongs to User
PhoneLineUserAssignment.belongsTo(User, {
  foreignKey: 'user_id',
  as: 'user',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// PhoneLineUserAssignment belongs to PhoneLine
PhoneLineUserAssignment.belongsTo(PhoneLine, {
  foreignKey: 'phone_line_id',
  as: 'phoneLine',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// User has many PhoneLineUserAssignments
User.hasMany(PhoneLineUserAssignment, {
  foreignKey: 'user_id',
  as: 'phoneLineAssignments',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// PhoneLine has many PhoneLineUserAssignments
PhoneLine.hasMany(PhoneLineUserAssignment, {
  foreignKey: 'phone_line_id',
  as: 'userAssignments',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

/**
 * PhoneLine associations with Messages and Leads
 */

// PhoneLine has many Messages
PhoneLine.hasMany(Message, {
  foreignKey: 'phone_line_id',
  as: 'messages',
  onDelete: 'RESTRICT',
  onUpdate: 'CASCADE',
});

// Message belongs to PhoneLine
Message.belongsTo(PhoneLine, {
  foreignKey: 'phone_line_id',
  as: 'phoneLine',
  onDelete: 'RESTRICT',
  onUpdate: 'CASCADE',
});

// PhoneLine has many Leads
PhoneLine.hasMany(Lead, {
  foreignKey: 'phone_line_id',
  as: 'leads',
  onDelete: 'SET NULL',
  onUpdate: 'CASCADE',
});

// Lead belongs to PhoneLine
Lead.belongsTo(PhoneLine, {
  foreignKey: 'phone_line_id',
  as: 'phoneLine',
  onDelete: 'SET NULL',
  onUpdate: 'CASCADE',
});

// PhoneLine has many ConversationAssignments
PhoneLine.hasMany(ConversationAssignment, {
  foreignKey: 'phone_line_id',
  as: 'conversationAssignments',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// ConversationAssignment belongs to PhoneLine
ConversationAssignment.belongsTo(PhoneLine, {
  foreignKey: 'phone_line_id',
  as: 'phoneLine',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

/**
 * AutomationRule Associations
 *
 * Relationships:
 * - AutomationRule belongs to WhatsAppLine
 * - AutomationRule belongs to MessageTemplate (optional)
 * - WhatsAppLine has many AutomationRules
 * - MessageTemplate has many AutomationRules
 */

// AutomationRule belongs to WhatsAppLine
AutomationRule.belongsTo(WhatsAppLine, {
  foreignKey: 'line_id',
  as: 'line',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// WhatsAppLine has many AutomationRules
WhatsAppLine.hasMany(AutomationRule, {
  foreignKey: 'line_id',
  as: 'automationRules',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// AutomationRule belongs to MessageTemplate (optional)
AutomationRule.belongsTo(MessageTemplate, {
  foreignKey: 'template_id',
  as: 'template',
  onDelete: 'SET NULL',
  onUpdate: 'CASCADE',
});

// MessageTemplate has many AutomationRules
MessageTemplate.hasMany(AutomationRule, {
  foreignKey: 'template_id',
  as: 'automationRules',
  onDelete: 'SET NULL',
  onUpdate: 'CASCADE',
});

/**
 * CampaignAgentAssignment Associations
 *
 * Relationships:
 * - CampaignAgentAssignment belongs to User (assigned agent)
 * - CampaignAgentAssignment belongs to WhatsAppLine
 * - CampaignAgentAssignment belongs to User (assigned_by)
 * - User has many CampaignAgentAssignments
 * - WhatsAppLine has many CampaignAgentAssignments
 */

// CampaignAgentAssignment belongs to User (assigned agent)
CampaignAgentAssignment.belongsTo(User, {
  foreignKey: 'user_id',
  as: 'assignedUser',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// User has many CampaignAgentAssignments (as assigned agent)
User.hasMany(CampaignAgentAssignment, {
  foreignKey: 'user_id',
  as: 'campaignAssignments',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// CampaignAgentAssignment belongs to WhatsAppLine
CampaignAgentAssignment.belongsTo(WhatsAppLine, {
  foreignKey: 'line_id',
  as: 'line',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// WhatsAppLine has many CampaignAgentAssignments
WhatsAppLine.hasMany(CampaignAgentAssignment, {
  foreignKey: 'line_id',
  as: 'campaignAssignments',
  onDelete: 'CASCADE',
  onUpdate: 'CASCADE',
});

// CampaignAgentAssignment belongs to User (assigned_by)
CampaignAgentAssignment.belongsTo(User, {
  foreignKey: 'assigned_by',
  as: 'assignedBy',
  onDelete: 'SET NULL',
  onUpdate: 'CASCADE',
});

// User has many CampaignAgentAssignments (as assigner)
User.hasMany(CampaignAgentAssignment, {
  foreignKey: 'assigned_by',
  as: 'campaignAssignmentsMade',
  onDelete: 'SET NULL',
  onUpdate: 'CASCADE',
});

// Export PhoneLineUserAssignment with other models
export { PhoneLineUserAssignment, AutomationRule, CampaignAgentAssignment };

