    97→      const response = await userService.updateUser(userId, updateData);
    98→
    99→      // Update user in state
   100→      set(state => ({
   101→        users: state.users.map(user =>
   102→          user.id === userId ? response.data : user
   103→        ),
   104→        selectedUser: state.selectedUser?.id === userId ? response.data : state.selectedUser,
   105→        loading: false
   106→      }));
   107→
   108→      return response.data;
