   217→  removeLineFromUser: async (userId, lineId) => {
   218→    set({ loading: true, error: null });
   219→    try {
   220→      await userService.removeLineFromUser(userId, lineId);
   221→
   222→      // Refresh user data to get updated line assignments
   223→      const response = await userService.getUserById(userId);
