     8→import api from './api';
     9→
    10→/**
    11→ * Get all users
    12→ *
    13→ * @param {Object} params - Query parameters
    14→ * @param {number} params.page - Page number
    15→ * @param {number} params.limit - Items per page
    16→ * @param {string} params.role - Filter by role (admin or agent)
    17→ * @param {boolean} params.is_active - Filter by active status
    18→ * @returns {Promise<Object>} Users data with pagination
    19→ */
    20→export const getUsers = async (params = {}) => {
    21→  try {
    22→    const response = await api.get('/users', { params });
    23→    return response.data;
    24→  } catch (error) {
    25→    throw new Error(error.response?.data?.error || 'Failed to fetch users');
    26→  }
    27→};
    28→
    29→/**
    30→ * Get single user by ID
    31→ *
    32→ * @param {number} userId - User ID
    33→ * @returns {Promise<Object>} User data
    34→ */
    35→export const getUserById = async (userId) => {
    36→  try {
    37→    const response = await api.get(`/users/${userId}`);
    38→    return response.data;
    39→  } catch (error) {
    40→    throw new Error(error.response?.data?.error || 'Failed to fetch user');
    41→  }
    42→};
    43→
    44→/**
    45→ * Create new user
    46→ *
    47→ * @param {Object} userData - User data
    48→ * @param {string} userData.email - User email
    49→ * @param {string} userData.password - User password
    50→ * @param {string} userData.name - User name
    51→ * @param {string} userData.phoneNumber - User phone number (optional)
    52→ * @param {string} userData.role - User role (admin or agent)
    53→ * @returns {Promise<Object>} Created user
    54→ */
    55→export const createUser = async (userData) => {
    56→  try {
    57→    const response = await api.post('/users', userData);
    58→    return response.data;
    59→  } catch (error) {
    60→    throw new Error(error.response?.data?.error || 'Failed to create user');
    61→  }
    62→};
    63→
    64→/**
    65→ * Update user
    66→ *
    67→ * @param {number} userId - User ID
    68→ * @param {Object} updateData - Fields to update
    69→ * @returns {Promise<Object>} Updated user
    70→ */
    71→export const updateUser = async (userId, updateData) => {
    72→  try {
    73→    const response = await api.patch(`/users/${userId}`, updateData);
    74→    return response.data;
    75→  } catch (error) {
    76→    throw new Error(error.response?.data?.error || 'Failed to update user');
    77→  }
    78→};
