     8→import { Router } from 'express';
     9→import getUsers from './index.js';
    10→import createUser from './create.js';
    11→import getUserById from './getById.js';
    12→import updateUser from './update.js';
    13→import deleteUser from './delete.js';
    14→import activateUser from './activate.js';
    15→import getAssignedLines from './getAssignedLines.js';
    16→import assignLines from './assignLines.js';
    17→import removeLineAssignment from './removeLineAssignment.js';
    18→import getMyLines from './me/lines.js';
    19→import getAgentsByLine from './getAgentsByLine.js';
    20→import { authenticateJWT } from '../../../middleware/authenticateJWT.js';
    21→import { authorizeRole } from '../../../middleware/authorizeRole.js';
    22→
    23→const router = Router();
    24→
    25→// GET /api/v1/users/agents/line/:lineId - Get agents by line
    26→router.get('/agents/line/:lineId', authenticateJWT, authorizeRole(['admin', 'agent']), getAgentsByLine);
    27→
    28→// GET /api/v1/users/me/lines - Get current user's assigned lines
    29→router.use('/', getMyLines);
