    39→
    40→// PATCH /api/v1/users/:userId - Update user
    41→router.use('/', updateUser);
    42→
    43→// DELETE /api/v1/users/:userId - Delete user
    44→router.use('/', deleteUser);
    45→
    46→// PUT /api/v1/users/:userId/activate - Activate user
    47→router.use('/', activateUser);
    48→
    49→// GET /api/v1/users/:userId/lines - Get assigned lines
    50→router.use('/', getAssignedLines);
    51→
    52→// POST /api/v1/users/:userId/lines - Assign lines to user
    53→router.use('/', assignLines);
    54→
    55→// DELETE /api/v1/users/:userId/lines/:lineId - Remove line assignment
