     6→ */
     7→
     8→import { Router } from 'express';
     9→import PhoneLineAssignmentService from '../../../services/PhoneLineAssignmentService.js';
    10→import { authenticateJWT } from '../../../middleware/authenticateJWT.js';
    11→import { authorizeRole } from '../../../middleware/authorizeRole.js';
    12→import { AppError } from '../../../middleware/errorHandler.js';
    13→
    14→const router = Router();
    15→
    16→/**
    17→ * @route POST /api/v1/users/:userId/lines
    18→ * @desc Assign lines to a user (agent only)
    19→ * @access Admin only
    20→ */
    21→router.post('/:userId/lines', authenticateJWT, authorizeRole(['admin']), async (req, res, next) => {
    22→  try {
    23→    const { userId } = req.params;
    24→    const { lineIds } = req.body;
    25→
    26→    if (!userId || isNaN(parseInt(userId))) {
    27→      throw new AppError('Invalid user ID', 400);
    28→    }
    29→
    30→    if (!lineIds || !Array.isArray(lineIds) || lineIds.length === 0) {
    31→      throw new AppError('lineIds must be a non-empty array', 400);
    32→    }
    33→
    34→    // Validate all lineIds are numbers
    35→    const invalidIds = lineIds.filter(id => isNaN(parseInt(id)));
    36→    if (invalidIds.length > 0) {
    37→      throw new AppError('All lineIds must be valid numbers', 400);
    38→    }
    39→
    40→    const result = await PhoneLineAssignmentService.replaceUserPhoneLineAssignments(
    41→      parseInt(userId),
    42→      lineIds.map(id => parseInt(id))
    43→    );
    44→
    45→    res.status(200).json({
    46→      success: true,
    47→      message: result.message,
    48→      data: {
    49→        assignedCount: result.assignedCount
    50→      }
    51→    });
    52→  } catch (error) {
    53→    next(error);
    54→  }
    55→});
    56→
    57→export default router;
