/**
 * Line Assignment Modal Component
 *
 * Modal for managing line assignments to users (agents)
 * Phase 5: User Story 3 - Agent User Creation and Line Assignment
 */

import { useState, useEffect } from 'react';
import { Modal, Form, Button, Alert, Badge, ListGroup, Spinner } from 'react-bootstrap';
import PropTypes from 'prop-types';
import useUsersStore from '../../store/usersStore';
import useLinesStore from '../../store/linesStore';
import './LineAssignmentModal.scss';

const LineAssignmentModal = ({ show, user, onClose, onSuccess }) => {
  const { assignLinesToUser, loading: userLoading, error } = useUsersStore();
  const { lines, fetchLines, loading: linesLoading } = useLinesStore();

  const [selectedLineIds, setSelectedLineIds] = useState([]);

  useEffect(() => {
    if (show) {
      // Fetch available lines
      fetchLines({ is_active: true });

      // Set currently assigned lines
      if (user && user.assignedLines) {
        setSelectedLineIds(user.assignedLines);
      }
    }
  }, [show, user, fetchLines]);

  const handleToggleLine = (lineId) => {
    setSelectedLineIds(prev => {
      if (prev.includes(lineId)) {
        return prev.filter(id => id !== lineId);
      } else {
        return [...prev, lineId];
      }
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      await assignLinesToUser(user.id, selectedLineIds);
      onSuccess();
    } catch (err) {
      console.error('Line assignment error:', err);
    }
  };

  const handleClose = () => {
    setSelectedLineIds([]);
    onClose();
  };

  return (
    <Modal
      show={show}
      onHide={handleClose}
      size="lg"
      scrollable
      backdrop="static"
      keyboard={!userLoading}
    >
      <Modal.Header closeButton={!userLoading}>
        <Modal.Title>
          <i className="bi bi-diagram-3 me-2"></i>
          Manage Line Assignments
        </Modal.Title>
      </Modal.Header>

      <Modal.Body>
        {error && (
          <Alert variant="danger" dismissible>
            {error}
          </Alert>
        )}

        <div className="mb-3">
          <h6>User: {user?.name}</h6>
          <p className="text-muted mb-0">
            <small>{user?.email}</small>
          </p>
        </div>

        <Form onSubmit={handleSubmit} id="line-assignment-form">
          <Form.Label className="mb-3">
            <strong>Select WhatsApp Lines to assign:</strong>
          </Form.Label>

          {linesLoading ? (
            <div className="text-center py-4">
              <Spinner animation="border" variant="primary" />
              <p className="mt-2 text-muted">Loading available lines...</p>
            </div>
          ) : lines.length === 0 ? (
            <Alert variant="info">
              No active WhatsApp lines available. Please create a line first.
            </Alert>
          ) : (
            <ListGroup className="line-assignment-list">
              {lines.map((line) => {
                const isSelected = selectedLineIds.includes(line.id);
                return (
                  <ListGroup.Item
                    key={line.id}
                    action
                    active={isSelected}
                    onClick={() => handleToggleLine(line.id)}
                    className="d-flex justify-content-between align-items-center"
                  >
                    <div>
                      <Form.Check
                        type="checkbox"
                        checked={isSelected}
                        onChange={() => {}} // Handled by ListGroup.Item onClick
                        label={
                          <div>
                            <strong>{line.company_name}</strong>
                            <br />
                            <small className="text-muted">{line.phone_number}</small>
                          </div>
                        }
                        className="mb-0"
                        readOnly
                      />
                    </div>
                    {line.is_active ? (
                      <Badge bg="success">Active</Badge>
                    ) : (
                      <Badge bg="secondary">Inactive</Badge>
                    )}
                  </ListGroup.Item>
                );
              })}
            </ListGroup>
          )}

          <div className="mt-3">
            <p className="text-muted mb-0">
              <small>
                <i className="bi bi-info-circle me-1"></i>
                Selected: <strong>{selectedLineIds.length}</strong> line(s)
              </small>
            </p>
          </div>
        </Form>
      </Modal.Body>

      <Modal.Footer>
        <Button
          variant="secondary"
          onClick={handleClose}
          disabled={userLoading}
        >
          Cancel
        </Button>
        <Button
          variant="primary"
          type="submit"
          form="line-assignment-form"
          disabled={userLoading || linesLoading}
        >
          {userLoading ? (
            <>
              <span className="spinner-border spinner-border-sm me-2" />
              Saving...
            </>
          ) : (
            'Save Assignments'
          )}
        </Button>
      </Modal.Footer>
    </Modal>
  );
};

LineAssignmentModal.propTypes = {
  show: PropTypes.bool.isRequired,
  user: PropTypes.object,
  onClose: PropTypes.func.isRequired,
  onSuccess: PropTypes.func.isRequired
};

LineAssignmentModal.defaultProps = {
  user: null
};

export default LineAssignmentModal;

