/**
 * UserAssignmentSelector Component
 *
 * Component for selecting and displaying assigned users with pills
 */

import { useState, useEffect } from 'react';
import { Form, Badge, Dropdown } from 'react-bootstrap';
import PropTypes from 'prop-types';
import './UserAssignmentSelector.scss';
import useUsersStore from '../../store/usersStore';

const UserAssignmentSelector = ({ selectedUserIds = [], onUsersChange }) => {
  const { users, fetchUsers, loading } = useUsersStore();
  const [searchTerm, setSearchTerm] = useState('');
  const [showDropdown, setShowDropdown] = useState(false);

  useEffect(() => {
    // Fetch only active agents and admins
    fetchUsers({ is_active: true });
  }, [fetchUsers]);

  // Filter users based on search term and exclude already selected
  const availableUsers = users.filter(user => {
    const matchesSearch = user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         user.email.toLowerCase().includes(searchTerm.toLowerCase());
    const notSelected = !selectedUserIds.includes(user.id);
    return matchesSearch && notSelected;
  });

  // Get selected users details
  const selectedUsers = users.filter(user => selectedUserIds.includes(user.id));

  const handleUserSelect = (userId) => {
    const newSelectedIds = [...selectedUserIds, userId];
    onUsersChange(newSelectedIds);
    setSearchTerm('');
    setShowDropdown(false);
  };

  const handleUserRemove = (userId) => {
    const newSelectedIds = selectedUserIds.filter(id => id !== userId);
    onUsersChange(newSelectedIds);
  };

  const getInitials = (name) => {
    return name
      .split(' ')
      .map(word => word[0])
      .join('')
      .toUpperCase()
      .substring(0, 2);
  };

  const getColorForUser = (userId) => {
    const colors = ['primary', 'success', 'info', 'warning', 'secondary'];
    return colors[userId % colors.length];
  };

  return (
    <div className="user-assignment-selector">
      <Form.Group className="mb-3">
        <Form.Label>Asignar usuarios</Form.Label>

        {/* Selected Users Pills */}
        <div className="selected-users mb-2">
          {selectedUsers.map(user => (
            <Badge
              key={user.id}
              bg={getColorForUser(user.id)}
              className="user-pill me-2 mb-2"
            >
              <span className="user-initials me-1">
                {getInitials(user.name)}
              </span>
              <span className="user-name">{user.name}</span>
              <button
                type="button"
                className="btn-remove-user"
                onClick={() => handleUserRemove(user.id)}
                aria-label={`Remover ${user.name}`}
              >
                ×
              </button>
            </Badge>
          ))}
        </div>

        {/* Search Input */}
        <Dropdown
          show={showDropdown}
          onToggle={(isOpen) => setShowDropdown(isOpen)}
        >
          <Form.Control
            type="text"
            placeholder="Buscar usuarios para asignar..."
            value={searchTerm}
            onChange={(e) => {
              setSearchTerm(e.target.value);
              setShowDropdown(true);
            }}
            onFocus={() => setShowDropdown(true)}
            disabled={loading}
          />

          {showDropdown && availableUsers.length > 0 && (
            <Dropdown.Menu show className="w-100">
              {availableUsers.map(user => (
                <Dropdown.Item
                  key={user.id}
                  onClick={() => handleUserSelect(user.id)}
                >
                  <div className="d-flex align-items-center">
                    <Badge
                      bg={getColorForUser(user.id)}
                      className="user-initials-badge me-2"
                    >
                      {getInitials(user.name)}
                    </Badge>
                    <div>
                      <div className="fw-bold">{user.name}</div>
                      <small className="text-muted">{user.email}</small>
                    </div>
                  </div>
                </Dropdown.Item>
              ))}
            </Dropdown.Menu>
          )}

          {showDropdown && searchTerm && availableUsers.length === 0 && (
            <Dropdown.Menu show className="w-100">
              <Dropdown.Item disabled>
                No se encontraron usuarios
              </Dropdown.Item>
            </Dropdown.Menu>
          )}
        </Dropdown>

        <Form.Text className="text-muted">
          {selectedUsers.length === 0
            ? 'No hay usuarios asignados'
            : `${selectedUsers.length} usuario(s) asignado(s)`}
        </Form.Text>
      </Form.Group>
    </div>
  );
};

UserAssignmentSelector.propTypes = {
  selectedUserIds: PropTypes.arrayOf(PropTypes.number),
  onUsersChange: PropTypes.func.isRequired
};

UserAssignmentSelector.defaultProps = {
  selectedUserIds: []
};

export default UserAssignmentSelector;

