/**
 * Phone Lines Store (Zustand)
 *
 * State management for WhatsApp phone lines
 */

import { create } from 'zustand';
import phoneLineService from '../services/phoneLineService';

const usePhoneLinesStore = create((set, get) => ({
  // State
  phoneLines: [],
  selectedPhoneLine: null,
  loading: false,
  error: null,
  pagination: {
    page: 1,
    limit: 10,
    total: 0,
    totalPages: 0
  },

  // Actions

  setPhoneLines: (newPhoneLines) => set({ phoneLines: newPhoneLines }),

  /**
   * Fetch all phone lines
   */
  fetchPhoneLines: async (params = {}) => {
    set({ loading: true, error: null });
    try {
      const response = await phoneLineService.getPhoneLines(params);
      set({
        phoneLines: response.data || [],
        pagination: response.pagination || {},
        loading: false
      });
    } catch (error) {
      set({
        error: error.message || 'Failed to fetch phone lines',
        loading: false
      });
    }
  },

  /**
   * Fetch phone lines by WABA ID
   */
  fetchPhoneLinesByWabaId: async (wabaId, activeOnly = true) => {
    set({ loading: true, error: null });
    try {
      const response = await phoneLineService.getPhoneLinesByWabaId(wabaId, activeOnly);
      set({
        phoneLines: response.data || [],
        loading: false
      });
    } catch (error) {
      set({
        error: error.message || 'Failed to fetch WABA phone lines',
        loading: false
      });
    }
  },

  /**
   * Fetch single phone line by ID
   */
  fetchPhoneLineById: async (phoneLineId) => {
    set({ loading: true, error: null });
    try {
      const response = await phoneLineService.getPhoneLineById(phoneLineId);
      set({
        selectedPhoneLine: response.data,
        loading: false
      });
      return response.data;
    } catch (error) {
      set({
        error: error.message || 'Failed to fetch phone line',
        loading: false
      });
      throw error;
    }
  },

  /**
   * Create new phone line
   */
  createPhoneLine: async (phoneLineData) => {
    set({ loading: true, error: null });
    try {
      const response = await phoneLineService.createPhoneLine(phoneLineData);

      // Add new phone line to state
      set(state => ({
        phoneLines: [response.data, ...state.phoneLines],
        loading: false
      }));

      return response.data;
    } catch (error) {
      set({
        error: error.message || 'Failed to create phone line',
        loading: false
      });
      throw error;
    }
  },

  /**
   * Update existing phone line
   */
  updatePhoneLine: async (phoneLineId, updateData) => {
    set({ loading: true, error: null });
    try {
      const response = await phoneLineService.updatePhoneLine(phoneLineId, updateData);

      // Update phone line in state
      set(state => ({
        phoneLines: state.phoneLines.map(phoneLine =>
          phoneLine.id === phoneLineId ? { ...phoneLine, ...response.data } : phoneLine
        ),
        selectedPhoneLine: state.selectedPhoneLine?.id === phoneLineId
          ? { ...state.selectedPhoneLine, ...response.data }
          : state.selectedPhoneLine,
        loading: false
      }));

      return response.data;
    } catch (error) {
      set({
        error: error.message || 'Failed to update phone line',
        loading: false
      });
      throw error;
    }
  },

  /**
   * Delete phone line
   */
  deletePhoneLine: async (phoneLineId) => {
    set({ loading: true, error: null });
    try {
      await phoneLineService.deletePhoneLine(phoneLineId);

      // Remove phone line from state
      set(state => ({
        phoneLines: state.phoneLines.filter(phoneLine => phoneLine.id !== phoneLineId),
        selectedPhoneLine: state.selectedPhoneLine?.id === phoneLineId ? null : state.selectedPhoneLine,
        loading: false
      }));
    } catch (error) {
      set({
        error: error.message || 'Failed to delete phone line',
        loading: false
      });
      throw error;
    }
  },

  /**
   * Activate phone line
   */
  activatePhoneLine: async (phoneLineId) => {
    set({ loading: true, error: null });
    try {
      const response = await phoneLineService.activatePhoneLine(phoneLineId);

      // Update phone line in state
      set(state => ({
        phoneLines: state.phoneLines.map(phoneLine =>
          phoneLine.id === phoneLineId ? { ...phoneLine, is_active: true } : phoneLine
        ),
        loading: false
      }));

      return response.data;
    } catch (error) {
      set({
        error: error.message || 'Failed to activate phone line',
        loading: false
      });
      throw error;
    }
  },

  /**
   * Deactivate phone line
   */
  deactivatePhoneLine: async (phoneLineId) => {
    set({ loading: true, error: null });
    try {
      const response = await phoneLineService.deactivatePhoneLine(phoneLineId);

      // Update phone line in state
      set(state => ({
        phoneLines: state.phoneLines.map(phoneLine =>
          phoneLine.id === phoneLineId ? { ...phoneLine, is_active: false } : phoneLine
        ),
        loading: false
      }));

      return response.data;
    } catch (error) {
      set({
        error: error.message || 'Failed to deactivate phone line',
        loading: false
      });
      throw error;
    }
  },

  /**
   * Clear error
   */
  clearError: () => set({ error: null }),

  /**
   * Clear selected phone line
   */
  clearSelectedPhoneLine: () => set({ selectedPhoneLine: null }),

  /**
   * Reset store
   */
  reset: () => set({
    phoneLines: [],
    selectedPhoneLine: null,
    loading: false,
    error: null,
    pagination: {
      page: 1,
      limit: 10,
      total: 0,
      totalPages: 0
    }
  })
}));

export default usePhoneLinesStore;

/**
 * PhoneLine Form Component
 *
 * Form for creating/editing WhatsApp line phoneLines
 */

import { useState, useEffect } from 'react';
import { Form, Button, Alert, Row, Col, Tabs, Tab, Card } from 'react-bootstrap';
import PropTypes from 'prop-types';
import './PhoneLineForm.scss';
import useLinesStore from '../../store/linesStore';
import UserAssignmentSelector from './UserAssignmentSelector';

const PhoneLineForm = ({ phoneLine, onSubmit, loading, error }) => {

  const fetchLines = useLinesStore((state) => state.fetchLines);

  const lines = useLinesStore((state) => state.lines);

  const [formData, setFormData] = useState({
    name: '',
    waba_id: '', // Foreign key to WhatsAppLine (business line)
    phone_number: '',
    phone_number_id: '',
    display_phone_number: '',
    verified_name: '',
    quality_rating: 'UNKNOWN',
    messaging_limit_tier: '',
    welcome_message_enabled: false,
    welcome_message: '',
    auto_reply_enabled: false,
    auto_reply_message: '',
    business_hours: {
      enabled: false,
      timezone: 'America/Mexico_City',
      schedule: {
        monday: { open: '09:00', close: '18:00', enabled: true },
        tuesday: { open: '09:00', close: '18:00', enabled: true },
        wednesday: { open: '09:00', close: '18:00', enabled: true },
        thursday: { open: '09:00', close: '18:00', enabled: true },
        friday: { open: '09:00', close: '18:00', enabled: true },
        saturday: { open: '09:00', close: '14:00', enabled: false },
        sunday: { open: '09:00', close: '14:00', enabled: false }
      }
    },
    out_of_hours_message: '',
    auto_assignment_enabled: false,
    max_conversations_per_agent: 10,
    is_active: true,
    assigned_user_ids: []
  });

  const [validated, setValidated] = useState(false);
  const [activeTab, setActiveTab] = useState('basic');

  // Fetch lines only once when component mounts
  useEffect(() => {
    fetchLines();
  }, [fetchLines]);

  // Initialize form data when phoneLine prop changes
  useEffect(() => {
    if (phoneLine) {

      setFormData({
        name: phoneLine.name?.trim() || '',
        waba_id: phoneLine.waba_id || '',
        phone_number: phoneLine.phone_number?.trim() || '',
        phone_number_id: phoneLine.phone_number_id?.trim() || '',
        display_phone_number: phoneLine.display_phone_number?.trim() || '',
        verified_name: phoneLine.verified_name?.trim() || '',
        quality_rating: phoneLine.quality_rating || 'UNKNOWN',
        messaging_limit_tier: phoneLine.messaging_limit_tier?.trim() || '',
        welcome_message_enabled: phoneLine.welcome_message_enabled || false,
        welcome_message: phoneLine.welcome_message || '',
        auto_reply_enabled: phoneLine.auto_reply_enabled || false,
        auto_reply_message: phoneLine.auto_reply_message || '',
        business_hours: phoneLine.business_hours || {
          enabled: false,
          timezone: 'America/Mexico_City',
          schedule: {
            monday: { open: '09:00', close: '18:00', enabled: true },
            tuesday: { open: '09:00', close: '18:00', enabled: true },
            wednesday: { open: '09:00', close: '18:00', enabled: true },
            thursday: { open: '09:00', close: '18:00', enabled: true },
            friday: { open: '09:00', close: '18:00', enabled: true },
            saturday: { open: '09:00', close: '14:00', enabled: false },
            sunday: { open: '09:00', close: '14:00', enabled: false }
          }
        },
        out_of_hours_message: phoneLine.out_of_hours_message || '',
        auto_assignment_enabled: phoneLine.auto_assignment_enabled || false,
        max_conversations_per_agent: phoneLine.max_conversations_per_agent || 10,
        is_active: phoneLine.is_active !== undefined ? phoneLine.is_active : true,
        assigned_user_ids: phoneLine.assigned_user_ids || []
      });
    }
  }, [phoneLine]);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    // Trim whitespace from text fields
    const processedValue = type === 'checkbox' ? checked : (type === 'text' ? value.trim() : value);
    setFormData(prev => ({
      ...prev,
      [name]: processedValue
    }));
  };

  const handleBusinessHoursChange = (field, value) => {
    setFormData(prev => ({
      ...prev,
      business_hours: {
        ...prev.business_hours,
        [field]: value
      }
    }));
  };

  const handleScheduleChange = (day, field, value) => {
    setFormData(prev => ({
      ...prev,
      business_hours: {
        ...prev.business_hours,
        schedule: {
          ...prev.business_hours.schedule,
          [day]: {
            ...prev.business_hours.schedule[day],
            [field]: value
          }
        }
      }
    }));
  };

  const handleUsersChange = (userIds) => {
    setFormData(prev => ({
      ...prev,
      assigned_user_ids: userIds
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const form = e.currentTarget;

    if (form.checkValidity() === false) {
      e.stopPropagation();
      setValidated(true);
      return;
    }

    onSubmit(formData);
  };

  const weekDays = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
  const dayLabels = {
    monday: 'Lunes',
    tuesday: 'Martes',
    wednesday: 'Miércoles',
    thursday: 'Jueves',
    friday: 'Viernes',
    saturday: 'Sábado',
    sunday: 'Domingo'
  };

  return (
    <Form noValidate validated={validated} onSubmit={handleSubmit} className="phoneLine-form">
      {error && (
        <Alert variant="danger" dismissible>
          {error}
        </Alert>
      )}

      <Tabs activeKey={activeTab} onSelect={(k) => setActiveTab(k)} className="mb-3">
        <Tab eventKey="basic" title="Información Básica">
          <Row>
            <Col md={12}>
              <Form.Group className="mb-3">
                <Form.Label>Nombre de línea *</Form.Label>
                <Form.Control
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  required
                  placeholder="Ej: Línea de Soporte"
                />
                <Form.Control.Feedback type="invalid">
                  El nombre de línea es requerido
                </Form.Control.Feedback>
              </Form.Group>
            </Col>
          </Row>

          <Row>
            <Col md={6}>
              <Form.Group className="mb-3">
                <Form.Label>Línea de negocio</Form.Label>
                <Form.Select
                  name="waba_id"
                  value={formData.waba_id}
                  onChange={handleChange}
                  required
                >
                  <option value="">Seleccionar línea de negocio</option>
                  {lines.filter(l => l.is_active).map(line => {
                    const optionValue = line.business_account_id || line.id;
                    console.log(`Line ${line.id}: business_account_id=${line.business_account_id}, using value=${optionValue}, matches=${optionValue === formData.waba_id}`);
                    return (
                      <option key={line.id} value={optionValue}>
                        {line.company_name} - {line.phone_number}
                      </option>
                    );
                  })}
                </Form.Select>
                <Form.Control.Feedback type="invalid">
                Línea de negocio es requerida
                </Form.Control.Feedback>
              </Form.Group>
            </Col>

            <Col md={6}>
              <Form.Group className="mb-3">
                <Form.Label>Número de teléfono (E.164) *</Form.Label>
                <Form.Control
                  type="text"
                  name="phone_number"
                  value={formData.phone_number}
                  onChange={handleChange}
                  required
                  placeholder="+1234567890"
                  pattern="^\+?[1-9]\d{1,14}$"
                />
                <Form.Control.Feedback type="invalid">
                  Formato E.164 válido requerido (ej: +1234567890)
                </Form.Control.Feedback>
              </Form.Group>
            </Col>

            <Col md={6}>
              <Form.Group className="mb-3">
                <Form.Label>ID número de teléfono (Meta) *</Form.Label>
                <Form.Control
                  type="text"
                  name="phone_number_id"
                  value={formData.phone_number_id}
                  onChange={handleChange}
                  required
                  placeholder="123456789012345"
                />
                <Form.Control.Feedback type="invalid">
                  ID número de teléfono  de Meta es requerido
                </Form.Control.Feedback>
              </Form.Group>
            </Col>
          </Row>

          <Row>
            <Col md={6}>
              <Form.Group className="mb-3">
                <Form.Label>Número para mostrar</Form.Label>
                <Form.Control
                  type="text"
                  name="display_phone_number"
                  value={formData.display_phone_number}
                  onChange={handleChange}
                  placeholder="+1 (555) 123-4567"
                />
              </Form.Group>
            </Col>

            <Col md={6}>
              <Form.Group className="mb-3">
                <Form.Label>Nombre verificado</Form.Label>
                <Form.Control
                  type="text"
                  name="verified_name"
                  value={formData.verified_name}
                  onChange={handleChange}
                  placeholder="Nombre del negocio"
                />
              </Form.Group>
            </Col>
          </Row>

          <Row>
            <Col md={6}>
              <Form.Group className="mb-3">
                <Form.Label>Calidad de línea</Form.Label>
                <Form.Select
                  name="quality_rating"
                  value={formData.quality_rating}
                  onChange={handleChange}
                >
                  <option value="UNKNOWN">Desconocida</option>
                  <option value="GREEN">Verde</option>
                  <option value="YELLOW">Amarillo</option>
                  <option value="RED">Rojo</option>
                </Form.Select>
              </Form.Group>
            </Col>

            <Col md={6}>
              <Form.Group className="mb-3">
                <Form.Label>Límite de mensajes</Form.Label>
                <Form.Control
                  type="text"
                  name="messaging_limit_tier"
                  value={formData.messaging_limit_tier}
                  onChange={handleChange}
                  placeholder="Ej: TIER_1K"
                />
              </Form.Group>
            </Col>
          </Row>
        </Tab>

        <Tab eventKey="messages" title="Mensajes Automáticos">
          <Card className="mb-3">
            <Card.Header>
              <Form.Check
                type="checkbox"
                name="welcome_message_enabled"
                label="Habilitar Mensaje de Bienvenida"
                checked={formData.welcome_message_enabled}
                onChange={handleChange}
              />
            </Card.Header>
            {formData.welcome_message_enabled && (
              <Card.Body>
                <Form.Group className="mb-3">
                  <Form.Label>Mensaje de Bienvenida</Form.Label>
                  <Form.Control
                    as="textarea"
                    rows={3}
                    name="welcome_message"
                    value={formData.welcome_message}
                    onChange={handleChange}
                    placeholder="¡Hola! Bienvenido a nuestro servicio..."
                    maxLength={1000}
                  />
                  <Form.Text className="text-muted">
                    {formData.welcome_message.length}/1000 caracteres
                  </Form.Text>
                </Form.Group>
              </Card.Body>
            )}
          </Card>

          <Card>
            <Card.Header>
              <Form.Check
                type="checkbox"
                name="auto_reply_enabled"
                label="Habilitar Respuesta Automática"
                checked={formData.auto_reply_enabled}
                onChange={handleChange}
              />
            </Card.Header>
            {formData.auto_reply_enabled && (
              <Card.Body>
                <Form.Group className="mb-3">
                  <Form.Label>Mensaje de Respuesta Automática</Form.Label>
                  <Form.Control
                    as="textarea"
                    rows={3}
                    name="auto_reply_message"
                    value={formData.auto_reply_message}
                    onChange={handleChange}
                    placeholder="Gracias por contactarnos. Un agente te atenderá pronto..."
                    maxLength={1000}
                  />
                  <Form.Text className="text-muted">
                    {formData.auto_reply_message.length}/1000 caracteres
                  </Form.Text>
                </Form.Group>
              </Card.Body>
            )}
          </Card>
        </Tab>

        <Tab eventKey="hours" title="Horario de Atención">
          <Form.Check
            type="checkbox"
            label="Habilitar Horario de Atención"
            checked={formData.business_hours.enabled}
            onChange={(e) => handleBusinessHoursChange('enabled', e.target.checked)}
            className="mb-3"
          />

          {formData.business_hours.enabled && (
            <>
              <Form.Group className="mb-4">
                <Form.Label>Zona Horaria</Form.Label>
                <Form.Select
                  value={formData.business_hours.timezone}
                  onChange={(e) => handleBusinessHoursChange('timezone', e.target.value)}
                >
                  <option value="America/Bogota">Bogotá (GMT-5)</option>
                  <option value="America/Mexico_City">Ciudad de México (GMT-6)</option>
                  <option value="America/New_York">Nueva York (GMT-5)</option>
                  <option value="America/Los_Angeles">Los Ángeles (GMT-8)</option>
                  <option value="UTC">UTC (GMT+0)</option>
                </Form.Select>
              </Form.Group>

              <div className="schedule-container">
                {weekDays.map((day) => (
                  <Card key={day} className="mb-2 day-schedule">
                    <Card.Body>
                      <Row className="align-items-center">
                        <Col md={3}>
                          <Form.Check
                            type="checkbox"
                            label={dayLabels[day]}
                            checked={formData.business_hours.schedule[day].enabled}
                            onChange={(e) => handleScheduleChange(day, 'enabled', e.target.checked)}
                          />
                        </Col>
                        {formData.business_hours.schedule[day].enabled && (
                          <>
                            <Col md={4}>
                              <Form.Group>
                                <Form.Label className="small">Apertura</Form.Label>
                                <Form.Control
                                  type="time"
                                  value={formData.business_hours.schedule[day].open}
                                  onChange={(e) => handleScheduleChange(day, 'open', e.target.value)}
                                />
                              </Form.Group>
                            </Col>
                            <Col md={4}>
                              <Form.Group>
                                <Form.Label className="small">Cierre</Form.Label>
                                <Form.Control
                                  type="time"
                                  value={formData.business_hours.schedule[day].close}
                                  onChange={(e) => handleScheduleChange(day, 'close', e.target.value)}
                                />
                              </Form.Group>
                            </Col>
                          </>
                        )}
                      </Row>
                    </Card.Body>
                  </Card>
                ))}
              </div>

              <Form.Group className="mt-3">
                <Form.Label>Mensaje Fuera de Horario</Form.Label>
                <Form.Control
                  as="textarea"
                  rows={2}
                  name="out_of_hours_message"
                  value={formData.out_of_hours_message}
                  onChange={handleChange}
                  placeholder="Estamos fuera de horario. Horario de atención: Lunes a Viernes 9:00 - 18:00"
                  maxLength={1000}
                />
              </Form.Group>
            </>
          )}
        </Tab>

        <Tab eventKey="assignment" title="Asignación Automática">
          <Form.Check
            type="checkbox"
            name="auto_assignment_enabled"
            label="Habilitar Asignación Automática de Conversaciones"
            checked={formData.auto_assignment_enabled}
            onChange={handleChange}
            className="mb-3"
          />

          {formData.auto_assignment_enabled && (
            <Form.Group className="mb-3">
              <Form.Label>Máximo de Conversaciones por Agente</Form.Label>
              <Form.Control
                type="number"
                name="max_conversations_per_agent"
                value={formData.max_conversations_per_agent}
                onChange={handleChange}
                min="1"
                max="100"
              />
              <Form.Text className="text-muted">
                Número máximo de conversaciones que un agente puede tener asignadas simultáneamente
              </Form.Text>
            </Form.Group>
          )}
        </Tab>

        <Tab eventKey="users" title="Asignación de Usuarios">
          <Card>
            <Card.Body>
              <Card.Text className="mb-3">
                Asigna usuarios (agentes o administradores) que tendrán acceso a esta línea telefónica.
                Los usuarios asignados podrán gestionar conversaciones y mensajes en esta línea.
              </Card.Text>
              <UserAssignmentSelector
                selectedUserIds={formData.assigned_user_ids}
                onUsersChange={handleUsersChange}
              />
            </Card.Body>
          </Card>
        </Tab>
      </Tabs>

      <div className="form-actions">
        <Button variant="primary" type="submit" disabled={loading}>
          {loading ? 'Guardando...' : phoneLine ? 'Actualizar Configuración' : 'Crear Configuración'}
        </Button>
      </div>
    </Form>
  );
};

PhoneLineForm.propTypes = {
  phoneLine: PropTypes.object,
  onSubmit: PropTypes.func.isRequired,
  loading: PropTypes.bool,
  error: PropTypes.string
};

PhoneLineForm.defaultProps = {
  phoneLine: null,
  loading: false,
  error: null
};

export default PhoneLineForm;

