/**
 * PhoneLine Modal Component
 *
 * Modal for creating/editing WhatsApp phone lines
 */

import { useState, useEffect } from 'react';
import { Modal } from 'react-bootstrap';
import PropTypes from 'prop-types';
import PhoneLineForm from './PhoneLineForm';
import usePhoneLinesStore from '../../store/phoneLinesStore';
import phoneLineService from '../../services/phoneLineService';

const PhoneLineModal = ({ show, phoneLine, onClose, onSuccess }) => {
  const { createPhoneLine, updatePhoneLine, loading, error } = usePhoneLinesStore();
  const [phoneLineWithUsers, setPhoneLineWithUsers] = useState(null);
  const [loadingUsers, setLoadingUsers] = useState(false);

  // Load assigned users when editing a phone line
  useEffect(() => {
    const loadAssignedUsers = async () => {
      if (phoneLine && phoneLine.id) {
        setLoadingUsers(true);
        try {
          const response = await phoneLineService.getPhoneLineAssignedUsers(phoneLine.id);
          const assignedUsers = response.data || [];
          setPhoneLineWithUsers({
            ...phoneLine,
            assigned_user_ids: assignedUsers.map(user => user.id)
          });
        } catch (err) {
          console.error('Failed to load assigned users:', err);
          setPhoneLineWithUsers(phoneLine);
        } finally {
          setLoadingUsers(false);
        }
      } else {
        setPhoneLineWithUsers(phoneLine);
      }
    };

    if (show) {
      loadAssignedUsers();
    }
  }, [phoneLine, show]);

  const handleSubmit = async (formData) => {
    try {
      let savedPhoneLine;
      const { assigned_user_ids, ...phoneLineData } = formData;

      if (phoneLine) {
        // Update existing phone line
        savedPhoneLine = await updatePhoneLine(phoneLine.id, phoneLineData);
      } else {
        // Create new phone line
        savedPhoneLine = await createPhoneLine(phoneLineData);
      }

      // Replace user assignments for the phone line (handles both assignment and unassignment)
      const phoneLineId = phoneLine ? phoneLine.id : savedPhoneLine.id;
      const userIdsToAssign = assigned_user_ids || [];
      await phoneLineService.replacePhoneLineUsers(phoneLineId, userIdsToAssign);

      onSuccess();
    } catch (err) {
      console.error('Phone line save error:', err);
    }
  };

  return (
    <Modal
      show={show}
      onHide={onClose}
      size="lg"
      scrollable
      backdrop="static"
      keyboard={!loading}
    >
      <Modal.Header closeButton={!loading && !loadingUsers}>
        <Modal.Title>
          <i className="bi bi-telephone me-2"></i>
          {phoneLine ? 'Editar Línea Telefónica' : 'Agregar Línea Telefónica'}
        </Modal.Title>
      </Modal.Header>
      <Modal.Body>
        {loadingUsers ? (
          <div className="text-center py-4">
            <div className="spinner-border text-primary" role="status">
              <span className="visually-hidden">Cargando usuarios asignados...</span>
            </div>
            <p className="mt-2 text-muted">Cargando usuarios asignados...</p>
          </div>
        ) : (
          <PhoneLineForm
            phoneLine={phoneLineWithUsers}
            onSubmit={handleSubmit}
            loading={loading}
            error={error}
          />
        )}
      </Modal.Body>
    </Modal>
  );
};

PhoneLineModal.propTypes = {
  show: PropTypes.bool.isRequired,
  phoneLine: PropTypes.object,
  onClose: PropTypes.func.isRequired,
  onSuccess: PropTypes.func.isRequired
};

PhoneLineModal.defaultProps = {
  phoneLine: null
};

export default PhoneLineModal;

