/**
 * PhoneLine Service
 *
 * API service for WhatsApp phone line management
 */

import api from './api';

/**
 * Get all phone lines
 *
 * @param {Object} params - Query parameters
 * @param {boolean} params.is_active - Filter by active status
 * @param {string} params.waba_id - Filter by WABA ID
 * @param {string} params.phone_number - Filter by phone number
 * @param {number} params.page - Page number
 * @param {number} params.limit - Items per page
 * @returns {Promise<Object>} Phone lines data with pagination
 */
export const getPhoneLines = async (params = {}) => {
  try {
    const response = await api.get('/phone-lines', { params });
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to fetch phone lines');
  }
};

/**
 * Get phone lines for a specific WABA
 *
 * @param {string} wabaId - WABA ID
 * @param {boolean} activeOnly - Filter only active lines
 * @returns {Promise<Object>} Phone lines for the WABA
 */
export const getPhoneLinesByWabaId = async (wabaId, activeOnly = true) => {
  try {
    const response = await api.get(`/phone-lines/waba/${wabaId}`, {
      params: { active_only: activeOnly }
    });
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to fetch WABA phone lines');
  }
};

/**
 * Get single phone line by ID
 *
 * @param {number} phoneLineId - Phone line ID
 * @returns {Promise<Object>} Phone line data
 */
export const getPhoneLineById = async (phoneLineId) => {
  try {
    const response = await api.get(`/phone-lines/${phoneLineId}`);
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to fetch phone line');
  }
};

/**
 * Create new phone line
 *
 * @param {Object} phoneLineData - Phone line data
 * @param {string} phoneLineData.waba_id - WABA ID
 * @param {string} phoneLineData.name - Display name
 * @param {string} phoneLineData.phone_number - Phone number (E.164)
 * @param {string} phoneLineData.phone_number_id - Meta Phone Number ID
 * @param {string} phoneLineData.display_phone_number - Display phone number
 * @param {string} phoneLineData.verified_name - Verified business name
 * @param {string} phoneLineData.quality_rating - Quality rating
 * @param {string} phoneLineData.messaging_limit_tier - Messaging limit tier
 * @param {boolean} phoneLineData.welcome_message_enabled - Enable welcome message
 * @param {string} phoneLineData.welcome_message - Welcome message text
 * @param {boolean} phoneLineData.auto_reply_enabled - Enable auto-reply
 * @param {string} phoneLineData.auto_reply_message - Auto-reply message text
 * @param {Object} phoneLineData.business_hours - Business hours configuration
 * @param {string} phoneLineData.out_of_hours_message - Out of hours message
 * @param {boolean} phoneLineData.auto_assignment_enabled - Enable auto-assignment
 * @param {number} phoneLineData.max_conversations_per_agent - Max conversations per agent
 * @param {Object} phoneLineData.metadata - Additional metadata
 * @returns {Promise<Object>} Created phone line
 */
export const createPhoneLine = async (phoneLineData) => {
  try {
    const response = await api.post('/phone-lines', phoneLineData);
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to create phone line');
  }
};

/**
 * Update phone line
 *
 * @param {number} phoneLineId - Phone line ID
 * @param {Object} updateData - Fields to update
 * @returns {Promise<Object>} Updated phone line
 */
export const updatePhoneLine = async (phoneLineId, updateData) => {
  try {
    const response = await api.patch(`/phone-lines/${phoneLineId}`, updateData);
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to update phone line');
  }
};

/**
 * Delete phone line
 *
 * @param {number} phoneLineId - Phone line ID
 * @returns {Promise<Object>} Deletion result
 */
export const deletePhoneLine = async (phoneLineId) => {
  try {
    const response = await api.delete(`/phone-lines/${phoneLineId}`);
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to delete phone line');
  }
};

/**
 * Activate phone line
 *
 * @param {number} phoneLineId - Phone line ID
 * @returns {Promise<Object>} Updated phone line
 */
export const activatePhoneLine = async (phoneLineId) => {
  try {
    const response = await api.patch(`/phone-lines/${phoneLineId}`, { is_active: true });
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to activate phone line');
  }
};

/**
 * Deactivate phone line
 *
 * @param {number} phoneLineId - Phone line ID
 * @returns {Promise<Object>} Updated phone line
 */
export const deactivatePhoneLine = async (phoneLineId) => {
  try {
    const response = await api.patch(`/phone-lines/${phoneLineId}`, { is_active: false });
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to deactivate phone line');
  }
};

/**
 * Get users assigned to a phone line
 *
 * @param {number} phoneLineId - Phone line ID
 * @returns {Promise<Array>} Assigned users
 */
export const getPhoneLineAssignedUsers = async (phoneLineId) => {
  try {
    const response = await api.get(`/phone-lines/${phoneLineId}/users`);
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to fetch assigned users');
  }
};

/**
 * Assign users to a phone line (adds to existing assignments)
 *
 * @param {number} phoneLineId - Phone line ID
 * @param {number[]} userIds - Array of user IDs to assign
 * @returns {Promise<Object>} Assignment result
 */
export const assignUsersToPhoneLine = async (phoneLineId, userIds) => {
  try {
    const response = await api.post(`/phone-lines/${phoneLineId}/users`, { userIds });
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to assign users');
  }
};

/**
 * Replace all user assignments for a phone line
 *
 * @param {number} phoneLineId - Phone line ID
 * @param {number[]} userIds - Array of user IDs to assign (replaces all existing)
 * @returns {Promise<Object>} Assignment result
 */
export const replacePhoneLineUsers = async (phoneLineId, userIds) => {
  try {
