/**
 * Phone Lines Router
 *
 * Mounts all phone line endpoints
 */

import { Router } from 'express';
import getPhoneLines from './index.js';
import createPhoneLine from './create.js';
import getPhoneLineById from './getById.js';
import updatePhoneLine from './update.js';
import deletePhoneLine from './delete.js';
import getAssignedUsers from './getAssignedUsers.js';
import assignUsers from './assignUsers.js';

const router = Router();

// GET /api/v1/phone-lines - Get all phone lines
router.use('/', getPhoneLines);

// POST /api/v1/phone-lines - Create new phone line
router.use('/', createPhoneLine);

// GET /api/v1/phone-lines/:phoneLineId - Get phone line by ID
router.use('/', getPhoneLineById);

// PATCH /api/v1/phone-lines/:phoneLineId - Update phone line
router.use('/', updatePhoneLine);

// DELETE /api/v1/phone-lines/:phoneLineId - Delete phone line
router.use('/', deletePhoneLine);

// GET /api/v1/phone-lines/:phoneLineId/users - Get assigned users
router.use('/', getAssignedUsers);

// POST /api/v1/phone-lines/:phoneLineId/users - Assign users to phone line
router.use('/', assignUsers);

export default router;

