/**
 * POST /api/v1/phone-lines/:phoneLineId/users
 * PUT /api/v1/phone-lines/:phoneLineId/users
 *
 * Assign users to a phone line
 * POST: Add users to existing assignments
 * PUT: Replace all user assignments
 */

import { Router } from 'express';
import PhoneLineAssignmentService from '../../../services/PhoneLineAssignmentService.js';
import { authenticateJWT } from '../../../middleware/authenticateJWT.js';
import { authorizeRole } from '../../../middleware/authorizeRole.js';
import { AppError } from '../../../middleware/errorHandler.js';

const router = Router();

/**
 * @route POST /api/v1/phone-lines/:phoneLineId/users
 * @desc Add users to a phone line (appends to existing assignments)
 * @access Admin only
 */
router.post('/:phoneLineId/users', authenticateJWT, authorizeRole(['admin']), async (req, res, next) => {
  try {
    const { phoneLineId } = req.params;
    const { userIds } = req.body;

    if (!phoneLineId || isNaN(parseInt(phoneLineId))) {
      throw new AppError('Invalid phone line ID', 400);
    }

    if (!userIds || !Array.isArray(userIds) || userIds.length === 0) {
      throw new AppError('userIds must be a non-empty array', 400);
    }

    // Validate all userIds are numbers
    const invalidIds = userIds.filter(id => isNaN(parseInt(id)));
    if (invalidIds.length > 0) {
      throw new AppError('All userIds must be valid numbers', 400);
    }

    // Assign each user to the phone line
    const results = await Promise.all(
      userIds.map(userId =>
        PhoneLineAssignmentService.assignPhoneLinesToUser(
          parseInt(userId),
          [parseInt(phoneLineId)]
        )
      )
    );

    res.status(200).json({
      success: true,
      message: `Successfully assigned ${userIds.length} user(s) to phone line`,
      data: {
        assignedCount: userIds.length
      }
    });
  } catch (error) {
    next(error);
  }
});

/**
 * @route PUT /api/v1/phone-lines/:phoneLineId/users
 * @desc Replace all user assignments for a phone line
 * @access Admin only
 */
router.put('/:phoneLineId/users', authenticateJWT, authorizeRole(['admin']), async (req, res, next) => {
  try {
    const { phoneLineId } = req.params;
    const { userIds } = req.body;

    if (!phoneLineId || isNaN(parseInt(phoneLineId))) {
      throw new AppError('Invalid phone line ID', 400);
    }

    if (!userIds || !Array.isArray(userIds)) {
      throw new AppError('userIds must be an array', 400);
    }

    // Validate all userIds are numbers
    const invalidIds = userIds.filter(id => isNaN(parseInt(id)));
    if (invalidIds.length > 0) {
      throw new AppError('All userIds must be valid numbers', 400);
    }

    // Convert userIds to integers
    const integerUserIds = userIds.map(id => parseInt(id));

    // Replace all user assignments for this phone line
    // This is the CORRECT approach: replace all users of ONE phone line
    const result = await PhoneLineAssignmentService.replacePhoneLineUserAssignments(
      parseInt(phoneLineId),
      integerUserIds
    );

    res.status(200).json({
      success: true,
      message: result.message,
      data: {
        assignedCount: result.assignedCount
      }
    });
  } catch (error) {
    next(error);
  }
});

export default router;

