/**
 * GET /api/v1/phone-lines
 *
 * Get all phone lines (with optional filters)
 */

import { Router } from 'express';
import PhoneLineService from '../../../services/PhoneLineService.js';
import { authenticateJWT } from '../../../middleware/authenticateJWT.js';
import { authorizeRole } from '../../../middleware/authorizeRole.js';

const router = Router();

/**
 * @route GET /api/v1/phone-lines
 * @desc Get all phone lines (admin: all lines, agent: assigned lines only)
 * @access Admin, Agent
 */
router.get('/', authenticateJWT, authorizeRole(['admin', 'agent']), async (req, res, next) => {
  try {
    const { is_active, waba_id, phone_number, page, limit } = req.query;
    const user = req.user;

    // Build filters
    const filters = {};
    if (is_active !== undefined) {
      filters.isActive = is_active === 'true';
    }
    if (waba_id) {
      filters.wabaId = waba_id;
    }
    if (phone_number) {
      filters.phoneNumber = phone_number;
    }

    // Pagination
    const pagination = {
      page: parseInt(page) || 1,
      limit: parseInt(limit) || 10
    };

    let result;

    if (user.role === 'admin') {
      // Admin: get all phone lines
      result = await PhoneLineService.getAllPhoneLines(filters, pagination);
    } else {
      // Agent: get only assigned phone lines
      const assignedLineIds = user.assignedLines || [];
      result = await PhoneLineService.getAllPhoneLines(filters, pagination);

      // Filter to only assigned lines
      result.phoneLines = result.phoneLines.filter(line =>
        assignedLineIds.includes(line.id)
      );
      result.pagination.total = result.phoneLines.length;
    }

    res.status(200).json({
      success: true,
      data: result.phoneLines,
      pagination: result.pagination
    });
  } catch (error) {
    next(error);
  }
});

/**
 * @route GET /api/v1/phone-lines/waba/:wabaId
 * @desc Get phone lines for a specific WABA
 * @access Admin, Agent
 */
router.get('/waba/:wabaId', authenticateJWT, authorizeRole(['admin', 'agent']), async (req, res, next) => {
  try {
    const { wabaId } = req.params;
    const { active_only } = req.query;

    const activeOnly = active_only === undefined || active_only === 'true';
    const phoneLines = await PhoneLineService.getPhoneLinesByWabaId(wabaId, activeOnly);

    res.status(200).json({
      success: true,
      data: phoneLines
    });
  } catch (error) {
    next(error);
  }
});

export default router;
